import { Component } from '@angular/core';
import { Form, GenericFormComponent } from '../../../shared/generic-form/generic-form.component';
import { Parentesco } from '../../../models/parentesco.model';
import { ParentescoService } from '../../../controllers/parentesco.service';
import { ActivatedRoute } from '@angular/router';
import { UtilsService } from '../../../services/utils.service';

const FORM_DEF:Form=[
  {
    key:'nombre',
    label:'Parentesco',
    type:'text',
    style:{
      div:'col-12 p-3'
    }
  }
]

@Component({
    selector: 'app-form-parentesco',
    imports: [
        GenericFormComponent
    ],
    templateUrl: './form-parentesco.component.html',
    styleUrl: './form-parentesco.component.css'
})
export class FormParentescoComponent {
  parentesco?:Parentesco
  form= FORM_DEF
  constructor(
    public parentescoController:ParentescoService,
    private route: ActivatedRoute,
    private utils: UtilsService,
  ){}

  ngOnInit(){
    this.route.paramMap.subscribe(async (params)=>{
      const id = this.utils.intOrNull(params.get('parentesco_id'))
      if(id){
        this.parentesco=await this.parentescoController.find(id)
      }
    })
  }
}
